def test_owned_cleanup_with_mocked_runner_only(tmp_path, capsys, phase):
    roots=[]
    def seed(root,pins):
        roots.append(root)
        return h.seed(root,pins)
    real_seed=h.seed
    def capture_seed(root,pins):
        roots.append(root)
        return real_seed(root,pins)
    class Runner:
        addresses=[('127.0.0.1',0)]
        async def setup(self):
            if phase=='setup': raise RuntimeError('synthetic setup')
        async def cleanup(self):
            if phase=='cleanup': raise RuntimeError('synthetic cleanup')
    class Site:
        def __init__(self,*args): pass
        async def start(self): pass
    info=tmp_path/'private.json'; cleanup=tmp_path/'cleanup.json'
    if phase=='private':
        def private_fail(path,data,mode):
            if path==info:
                path.write_text('preserved competing value')
            return real_exclusive(path,data,mode)
    else: private_fail=None
    real_exclusive=h.exclusive
    async def run():
        loop=asyncio.get_running_loop()
        with patch.object(loop,'add_signal_handler',side_effect=lambda sig,callback: callback()), \
             patch.object(h,'build_manifest',return_value={'source_head':'a'*40,'helper':h.regular(SOURCE)}), \
             patch.object(h,'create_app',return_value=object()), \
             patch.object(h.web,'AppRunner',return_value=Runner()), \
             patch.object(h.web,'TCPSite',Site), \
             patch.object(h,'seed',side_effect=capture_seed):
            if private_fail:
                with patch.object(h,'exclusive',side_effect=private_fail):
                    await h.serve(argparse.Namespace(info=info,cleanup=cleanup,static=tmp_path,port=0))
            else:
                await h.serve(argparse.Namespace(info=info,cleanup=cleanup,static=tmp_path,port=0))
    if phase=='normal': asyncio.run(run())
    else:
        with pytest.raises((RuntimeError,FileExistsError)): asyncio.run(run())
    record=json.loads(cleanup.read_text())
    assert roots and all(not root.exists() for root in roots)
    assert record['fixture_removed'] and record['port_free']
    assert record['runners_closed']==(0 if phase=='cleanup' else 1)
    assert ('RuntimeError' in record['cleanup_errors'])==(phase=='cleanup')
    if phase=='private': assert info.read_text()=='preserved competing value'
    else: assert not info.exists()
    public=capsys.readouterr().out+cleanup.read_text()
    assert 'login_url' not in public and 'token=' not in public

@pytest.mark.parametrize('suffix', ['', '-wal', '-shm'])
def test_database_size_guard_precedes_open(suffix):
    root=Path(tempfile.mkdtemp(prefix=h.PREFIX)); root.chmod(0o700)
    try:
        h.seed(root,{'source_head':'a'*40,'helper':h.regular(SOURCE)})
        path=Path(str(h.store_path(root))+suffix)
        with path.open('wb') as stream: stream.truncate(32*1024*1024+1)
        with patch.object(h,'DocumentStore',side_effect=AssertionError('must not open SQLite')):
            with pytest.raises(ValueError,match='control-store'): h.action(root,'inspect')
    finally: shutil.rmtree(root)
